/* one POSIX queue per message type; the name is the type binding */
int q = mq_open("/orders", O_RDONLY);
struct order o;
while (mq_receive(q, (char *)&o, sizeof o, NULL) > 0)
    handle_order(&o);          /* no type tag: the channel told us the type */

int out = mq_open("/orders", O_WRONLY);
mq_send(out, (const char *)&o, sizeof o, 0);
